const control = $('Fetch Control Details').first().json;
const extractResponse = $('Extract Text via FastAPI').first().json;
const extracted = extractResponse.extracted_text || '';
const artifact_id = $('Webhook').first().json.body.artifact_id;
const program_control_id = $('Webhook').first().json.body.program_control_id;

const prompt = `CONTROL ID: ${control.cmmc_id}\n\nCONTROL REQUIREMENT: ${control.requirement_text}\n\nASSESSMENT OBJECTIVE: ${control.assessment_objective || 'Not specified'}\n\nACCEPTABLE PROOF CRITERIA:\n${control.acceptable_proof_guidance || 'Review against NIST SP 800-171 requirements'}\n\nSUBMITTED ARTIFACT CONTENT:\n${extracted.substring(0, 8000)}\n\nAssess whether this artifact satisfies the control requirement. Respond ONLY with this JSON structure, no other text:\n{"verdict":"pass|partial|fail","confidence":0.0,"rationale":"explanation","gaps":["gap1"]}`;

return [{
  json: {
    prompt,
    control_id: control.nist_id,
    program_id: control.program_id,
    artifact_id,
    program_control_id,
    extracted_text: extracted
  }
}];

const response = $input.first().json;
const content = response.choices && response.choices[0] ? response.choices[0].message.content : '';
let parsed;
try {
  parsed = JSON.parse(content);
} catch(e) {
  parsed = { verdict: 'fail', confidence: 0.5, rationale: 'Could not parse assessment response', gaps: ['Parse error'] };
}

const promptNode = $('Build Claude Prompt').first().json;

return [{
  json: {
    verdict: parsed.verdict || 'fail',
    confidence: typeof parsed.confidence === 'number' ? parsed.confidence : 0.5,
    rationale: parsed.rationale || '',
    gaps: JSON.stringify(parsed.gaps || []),
    model_used: 'openrouter/auto',
    artifact_id: promptNode.artifact_id,
    program_control_id: promptNode.program_control_id,
    program_id: promptNode.program_id,
    extracted_text: promptNode.extracted_text
  }
}];
